from modele import chapitre,E,Q

chapitre(13,'pythagore','Le théorème de Pythagore','4 · Géométrie et espace',
'Triangle rectangle · Longueurs · Réciproque',
['Calculer un côté d’un triangle rectangle.','Démontrer qu’un triangle est rectangle ou ne l’est pas.','Rédiger et contrôler une solution géométrique.'],
['Carrés, racines carrées et triangles.'],[
r'''\essSection{1}{Calculer dans un triangle rectangle}
\begin{propriete}[Théorème de Pythagore]Si ABC est rectangle en A, alors $BC^2=AB^2+AC^2$. Le côté opposé à l’angle droit, BC, est l’hypoténuse : c’est le plus long côté. Le théorème relie les aires des carrés construits sur les trois côtés.\end{propriete}
@FIG:cours-pythagore@
\begin{exemple}Si $AB=3$ et $AC=4$ cm, alors $BC^2=9+16=25$, donc $BC=\sqrt{25}=5$ cm. Si $BC=13$ et $AB=5$ cm, alors $AC^2=13^2-5^2=144$, donc $AC=12$ cm.\end{exemple}
\begin{attention}On additionne les carrés pour chercher l’hypoténuse ; on soustrait pour chercher un côté de l’angle droit. Écrire d’abord l’égalité avec les noms des points aide à éviter cette confusion.\end{attention}''',
r'''\essSection{2}{Reconnaître et prouver}
\begin{propriete}[Réciproque]Si, dans un triangle, le carré du plus long côté est égal à la somme des carrés des deux autres, alors ce triangle est rectangle. L’angle droit est opposé au plus long côté.\end{propriete}
\begin{savoirfaire}[Prouver ou réfuter]Identifier le plus long côté. Calculer séparément son carré et la somme des deux autres carrés. Comparer : une égalité permet d’utiliser la réciproque ; une inégalité montre que le triangle n’est pas rectangle, car un triangle rectangle respecterait Pythagore.\end{savoirfaire}
\begin{exemple}Pour des côtés 6, 8, 10, $10^2=100=36+64$ : le triangle est rectangle. Pour 6, 8, 11, $11^2=121\ne100$ : il ne l’est pas. Un dessin qui paraît rectangle ne suffit pas.\end{exemple}
\begin{savoirfaire}[Rédiger]Donner le triangle et l’hypothèse d’angle droit, citer le théorème, écrire l’égalité, calculer, prendre la racine positive et conclure avec l’unité. Pour une réciproque, annoncer la comparaison puis le sommet de l’angle droit. Garder la valeur exacte avant l’arrondi final.\end{savoirfaire}'''],[
E('Chercher l’hypoténuse',r"ABC est rectangle en A, $AB=6$ cm et $AC=8$ cm. Calculer BC.",r"Dans ABC rectangle en A, Pythagore donne $BC^2=6^2+8^2=100$. Comme BC est une longueur, $BC=\sqrt{100}=\res{10\ \mathrm{cm}}$. Elle dépasse bien chacun des deux autres côtés.","Additionner les carrés des côtés de l’angle droit.","assert sqrt(6**2+8**2)==10",figure='pyth-01'),
E('Chercher un petit côté',r"ABC est rectangle en A, $AB=5$ cm et $BC=13$ cm. Calculer AC.",r"BC est l’hypoténuse : $13^2=5^2+AC^2$. Donc $AC^2=169-25=144$ et $\res{AC=12\ \mathrm{cm}}$. Contrôle : $25+144=169$.","Soustraire au carré de l’hypoténuse.","assert sqrt(13**2-5**2)==12",figure='pyth-02'),
E('Une racine non entière',r"ABC est rectangle en A avec $AB=7$ cm et $AC=9$ cm. Donner BC exactement puis au dixième.",r"$BC^2=49+81=130$, donc $\res{BC=\sqrt{130}\ \mathrm{cm}}$. Au dixième, $BC\approx\res{11{,}4\ \mathrm{cm}}$. On conserve la racine pour la valeur exacte.","Distinguer valeur exacte et approximation.","assert sqrt(7**2+9**2)==sqrt(130) and round(float(sqrt(130)),1)==11.4",figure='pyth-03'),
E('L’hypoténuse donnée',r"ABC est rectangle en A, $BC=17$ cm et $AB=15$ cm. Calculer AC.",r"$AC^2=BC^2-AB^2=289-225=64$. Donc $\res{AC=8\ \mathrm{cm}}$. BC reste le plus long côté.","Repérer l’hypoténuse avant le calcul.","assert sqrt(17**2-15**2)==8",figure='pyth-04'),
E('Une réciproque',r"Un triangle ABC a pour côtés $AB=9$, $AC=12$, $BC=15$ cm. Est-il rectangle ?",r"BC est le plus long côté. $BC^2=225$ et $AB^2+AC^2=81+144=225$. L’égalité permet d’appliquer la réciproque de Pythagore : $\res{\text{ABC est rectangle en A}}$.","Comparer deux calculs distincts.","assert 15**2==9**2+12**2",figure='pyth-05'),
E('Un triangle non rectangle',r"Un triangle ABC a pour côtés $AB=4$, $AC=5$, $BC=7$ cm. Est-il rectangle ?",r"BC est le plus long côté. $7^2=49$, tandis que $4^2+5^2=41$. Les résultats sont différents : ABC n’est pas rectangle. Si le triangle l’était, le théorème imposerait leur égalité.","Utiliser l’inégalité pour exclure le caractère rectangle.","assert 7**2!=4**2+5**2 and 4+5>7",figure='pyth-06'),
E('Diagonale d’un rectangle',r"Un rectangle mesure 8 cm sur 6 cm. Calculer la longueur de sa diagonale.",r"La diagonale est l’hypoténuse d’un triangle rectangle dont les deux autres côtés mesurent 8 et 6 cm. Son carré vaut $64+36=100$ : elle mesure $\res{10\ \mathrm{cm}}$.","Faire apparaître un triangle rectangle.","assert sqrt(8**2+6**2)==10",figure='pyth-07'),
E('Une échelle dans un modèle',r"Une échelle de 2,5 m repose contre un mur perpendiculaire au sol. Son pied est à 0,8 m du mur. À quelle hauteur arrive-t-elle, au centimètre près ?",r"Le mur et le sol forment un triangle rectangle ; l’échelle est l’hypoténuse. $h^2=2{,}5^2-0{,}8^2=5{,}61$, donc $h=\sqrt{5{,}61}\approx\res{2{,}37\ \mathrm m}$. Les deux mesures étaient bien en mètres.","Modéliser la situation avant de calculer.","assert round(float(sqrt(Rational('2.5')**2-Rational('.8')**2)),2)==2.37",figure='pyth-08'),
E('Une distance dans un repère',r"Dans un repère orthonormé, $A(0;0)$, $B(6;0)$ et $C(0;8)$, unité 1 cm. Calculer BC.",r"AB et AC sont portés par les deux axes perpendiculaires, donc ABC est rectangle en A. $AB=6$ et $AC=8$ cm ; Pythagore donne $\res{BC=10\ \mathrm{cm}}$. On justifie l’angle droit par le repère orthonormé.","Lire les écarts sur les axes puis utiliser Pythagore.","assert sqrt(6**2+8**2)==10",figure='pyth-09'),
E('Trouver le bon sommet',r"$AB=10{,}5$, $AC=6{,}3$, $BC=8{,}4$ cm. Démontrer que ABC est rectangle et préciser le sommet.",r"Le plus long côté est AB. $AB^2=110{,}25$ et $AC^2+BC^2=39{,}69+70{,}56=110{,}25$. La réciproque montre que le triangle est rectangle au sommet opposé à AB, donc $\res{\text{en C}}$.","Placer l’angle droit en face du plus long côté.","assert Rational('10.5')**2==Rational('6.3')**2+Rational('8.4')**2",figure='pyth-10'),
E('Un losange',r"Un losange a pour diagonales 10 et 24 cm. Elles se coupent perpendiculairement en leur milieu. Calculer le côté et le périmètre.",r"Un quart du losange est un triangle rectangle de côtés de l’angle droit 5 et 12 cm. Le côté du losange vaut $\sqrt{25+144}=\res{13}$ cm. Son périmètre est $4\times13=\res{52}$ cm.","Utiliser les demi-diagonales.","assert sqrt(5**2+12**2)==13 and 4*13==52",figure='pyth-11'),
E('Retrouver une aire',r"Un rectangle a une diagonale de 13 cm et une largeur de 5 cm. Calculer sa longueur puis son aire.",r"Pour la longueur $L$, $L^2=13^2-5^2=144$, donc $L=12$ cm. L’aire vaut $12\times5=\res{60\ \mathrm{cm}^2}$. Ne pas confondre la diagonale avec une dimension du rectangle.","Retrouver la dimension avant de calculer l’aire.","assert sqrt(13**2-5**2)==12 and 12*5==60",figure='pyth-12'),
E('Deux diagonales',r"Un câble suit la diagonale d’un rectangle de 8 m sur 6 m, puis celle d’un rectangle de 10 m sur 24 m. Les deux parcours se rejoignent sans longueur supplémentaire. Calculer la longueur totale.",r"La première diagonale vaut $\sqrt{8^2+6^2}=10$ m. La seconde vaut $\sqrt{10^2+24^2}=26$ m. On additionne les longueurs, pas leurs carrés : total $\res{36\ \mathrm m}$.","Traiter chaque triangle rectangle séparément.","assert sqrt(8**2+6**2)+sqrt(10**2+24**2)==36",figure='pyth-13'),
E('Une précision décisive',r"Une barre rigide de 8 cm doit relier les extrémités de deux côtés perpendiculaires de 4 cm et 7 cm. Est-elle assez longue ? Justifier exactement.",r"La distance à couvrir vaut $\sqrt{4^2+7^2}=\sqrt{65}$ cm. Or $8^2=64<65$, donc $\sqrt{65}>8$. La barre est trop courte. Un arrondi trop grossier à 8 cm ferait perdre l’information décisive.","Comparer les carrés pour une décision exacte.","assert sqrt(65)>8",figure='pyth-14'),
E('Choisir un trajet',r"Un terrain rectangulaire mesure 12 m sur 5 m. Comparer un trajet le long de deux côtés adjacents avec la diagonale. Quelle longueur gagne-t-on avec la diagonale ?",r"Le trajet sur les côtés vaut $12+5=17$ m. La diagonale vaut $\sqrt{12^2+5^2}=13$ m par Pythagore. Le gain est $17-13=\res4$ m. La comparaison porte sur des longueurs dans la même unité.","Calculer les deux parcours avant de comparer.","assert 12+5-sqrt(12**2+5**2)==4",figure='pyth-15')
],reperes=['Calculer une hypoténuse','Calculer un côté de l’angle droit','Réciproque et triangle non rectangle','Applications et précision des résultats'],deco='geometrie')

chapitre(14,'thales','Thalès : triangles emboîtés','4 · Géométrie et espace',
'Alignement · Parallélisme · Rapports · Réciproque',
['Utiliser Thalès dans des triangles emboîtés.','Démontrer un parallélisme avec la réciproque.','Vérifier l’ordre des points et les côtés correspondants.'],
['Fractions, proportionnalité et équations simples.'],[
r'''\essSection{1}{Des côtés proportionnels}
\begin{propriete}[Théorème de Thalès]Dans le triangle ABC, M appartient à $[AB]$ et N à $[AC]$, avec M et N distincts de A. Si $(MN)$ est parallèle à $(BC)$, alors $\frac{AM}{AB}=\frac{AN}{AC}=\frac{MN}{BC}$. Les petits côtés sont tous au numérateur, les grands tous au dénominateur.\end{propriete}
@FIG:cours-thales@
\begin{exemple}Si $AB=8$, $AC=10$, $AM=4$ cm et $(MN)\parallel(BC)$, alors $AN/10=4/8=1/2$, donc $AN=5$ cm. Il faut annoncer les alignements et le parallélisme avant les rapports.\end{exemple}
\begin{attention}$AM$ est une distance depuis A, pas le morceau MB. Si $AB=8$ et $MB=3$, alors $AM=8-3=5$. Un schéma avec des points nommés évite de mélanger ces segments.\end{attention}''',
r'''\essSection{2}{Prouver un parallélisme}
\begin{propriete}[Réciproque]Dans un triangle ABC, M est sur $[AB]$ et N sur $[AC]$, distincts de A. Si $AM/AB=AN/AC$, alors les droites $(MN)$ et $(BC)$ sont parallèles. Les alignements et l’ordre des points font partie des conditions.\end{propriete}
\begin{exemple}Si $AM=3$, $AB=9$, $AN=4$, $AC=12$ cm, les deux rapports valent $1/3$. Avec les appartenances aux segments, la réciproque donne $(MN)\parallel(BC)$. Si les deux rapports sont différents, ce parallélisme est impossible : il imposerait l’égalité par le théorème direct.\end{exemple}
\begin{savoirfaire}[Choisir le sens]Pour calculer une longueur, on utilise généralement le théorème direct à partir d’un parallélisme connu. Pour prouver le parallélisme, on utilise la réciproque à partir des rapports de longueurs. Écrire les deux rapports avec le même sommet de départ et comparer exactement.\end{savoirfaire}
\begin{attention}Cette édition étudie la configuration des triangles emboîtés attendue en Quatrième. La configuration en papillon et les triangles semblables seront repris en Troisième. Une simple impression de parallélisme sur le dessin n’est pas une hypothèse.\end{attention}'''],[
E('Un rapport simple',r"Dans ABC, $M\in[AB]$, $N\in[AC]$ et $(MN)\parallel(BC)$. $AB=8$, $AC=10$ et $AM=4$ cm. Calculer AN.",r"Les points sont alignés dans l’ordre et les droites parallèles. Thalès donne $AN/10=AM/AB=4/8=1/2$. Donc $\res{AN=5\ \mathrm{cm}}$.","Relier petit et grand côtés correspondants.","assert Rational(4,8)*10==5",figure='th-01'),
E('Le segment parallèle',r"M et N sont sur $[AB]$ et $[AC]$, avec $(MN)\parallel(BC)$. $AB=12$, $AM=8$ et $BC=9$ cm. Calculer MN.",r"Par Thalès, $MN/9=8/12=2/3$. Donc $MN=9\times2/3=\res6$ cm. La longueur est plus petite que BC, ce qui est cohérent avec les triangles emboîtés.","Utiliser le rapport de réduction.","assert Rational(8,12)*9==6",figure='th-02'),
E('Retrouver le grand côté',r"M et N sont sur les segments du triangle ABC et $(MN)\parallel(BC)$. $AM=3$, $AB=9$ et $MN=4$ cm. Calculer BC.",r"$MN/BC=AM/AB=1/3$. Ainsi $4/BC=1/3$, donc $\res{BC=12\ \mathrm{cm}}$. On multiplie ici le petit côté par 3 pour revenir au grand.","Inverser le passage du grand vers le petit.","assert 4/Rational(3,9)==12",figure='th-03'),
E('Une réciproque',r"$M\in[AB]$, $N\in[AC]$, $AB=10$, $AM=6$, $AC=8$ et $AN=4{,}8$ cm. Démontrer $(MN)\parallel(BC)$.",r"$AM/AB=6/10=3/5$ et $AN/AC=4{,}8/8=3/5$. Les points sont sur les segments correspondants et les rapports sont égaux. La réciproque de Thalès donne $\res{(MN)\parallel(BC)}$.","Vérifier les deux conditions d’alignement et les rapports.","assert Rational(6,10)==Rational('4.8')/8",figure='th-04'),
E('Des rapports à simplifier',r"$M\in[AB]$, $N\in[AC]$, $AB=9$, $AM=6$, $AC=12$ et $AN=8$ cm. Les droites MN et BC sont-elles parallèles ?",r"$6/9=2/3$ et $8/12=2/3$. Avec les points sur les segments, la réciproque s’applique : les droites sont parallèles.","Comparer exactement deux fractions.","assert Rational(6,9)==Rational(8,12)",figure='th-05'),
E('Un parallélisme impossible',r"$M\in[AB]$, $N\in[AC]$, $AB=10$, $AM=6$, $AC=15$ et $AN=8$ cm. Les droites MN et BC peuvent-elles être parallèles ?",r"$AM/AB=3/5$ et $AN/AC=8/15$. Or $3/5=9/15\ne8/15$. Si les droites étaient parallèles, Thalès imposerait l’égalité. Elles ne sont donc pas parallèles.","Utiliser le théorème pour exclure une hypothèse.","assert Rational(6,10)!=Rational(8,15)",figure='th-06'),
E('Calculer le bon segment',r"Dans ABC, $M\in[AB]$, $N\in[AC]$ et $(MN)\parallel(BC)$. $AB=12$, $BM=3$ et $AC=8$ cm. Calculer AN.",r"$AM=AB-BM=12-3=9$ cm. Thalès donne $AN/8=9/12=3/4$, donc $\res{AN=6\ \mathrm{cm}}$. Utiliser BM à la place de AM donnerait le mauvais rapport.","Reconstituer la longueur depuis le sommet commun.","assert Rational(12-3,12)*8==6",figure='th-07'),
E('Un coefficient décimal',r"Dans la configuration emboîtée, $(MN)\parallel(BC)$, $AB=10$, $AM=4$, $AC=20$ et $BC=15$ cm. Calculer AN et MN.",r"Le rapport petit sur grand vaut $4/10=0{,}4$. Donc $AN=0{,}4\times20=\res8$ cm et $MN=0{,}4\times15=\res6$ cm. Le même coefficient s’applique aux côtés correspondants.","Utiliser une seule fois le coefficient commun.","assert Rational(4,10)*20==8 and Rational(4,10)*15==6",figure='th-08'),
E('Un protocole de construction',r"Tracer un triangle ABC avec $AB=9$ cm, $AC=12$ cm et $\widehat{BAC}=50^\circ$. Placer M à 3 cm de A sur AB, puis construire N pour que $(MN)\parallel(BC)$. Donner AN.",r"Construire ABC par CAC, placer M sur $[AB]$, puis tracer la parallèle à BC passant par M. Son intersection avec AC est N. Le rapport est $3/9=1/3$ ; Thalès donne $\res{AN=4\ \mathrm{cm}}$.","Construire le parallélisme avant de calculer.","assert Rational(3,9)*12==4",figure='th-09'),
E('Une proportion inverse',r"Dans les triangles emboîtés AMN et ABC avec $(MN)\parallel(BC)$, $AB=7$, $BC=14$ et $MN=5$ cm. Calculer AM.",r"$AM/7=MN/BC=5/14$. Donc $AM=7\times5/14=\res{2{,}5\ \mathrm{cm}}$. La valeur est inférieure à AB, comme l’exige M sur le segment.","Isoler le petit côté dans le rapport.","assert 7*Rational(5,14)==Rational('2.5')",figure='th-10'),
E('Une hauteur par proportion',r"Dans un modèle d’ombres, A, M, B sont alignés au sol avec $AM=2$ m, $AB=10$ m. MN et BC sont verticaux, $MN=1{,}5$ m, et A, N, C sont alignés. Calculer BC.",r"Les verticales MN et BC sont parallèles, et les deux alignements sont donnés. Par Thalès, $MN/BC=AM/AB=1/5$. Donc $BC=1{,}5\times5=\res{7{,}5\ \mathrm m}$. Le modèle suppose les alignements annoncés.","Justifier le parallélisme par les verticales.","assert Rational('1.5')*10/2==Rational('7.5')",figure='th-11'),
E('Un morceau restant',r"$AB=8$, $AM=3$, $AC=10$ cm, avec M et N sur les segments et $(MN)\parallel(BC)$. Calculer AN puis NC.",r"$AN/10=3/8$, d’où $AN=30/8=\res{3{,}75}$ cm. Comme N est entre A et C, $NC=AC-AN=10-3{,}75=\res{6{,}25}$ cm.","Calculer depuis A puis soustraire au grand côté.","assert 10*Rational(3,8)==Rational('3.75') and 10-Rational('3.75')==Rational('6.25')",figure='th-12'),
E('Justifier puis calculer',r"$M\in[AB]$, $N\in[AC]$, $AB=10$, $AC=15$, $AM=4$, $AN=6$ et $BC=12$ cm. Démontrer le parallélisme puis calculer MN.",r"$4/10=6/15=2/5$. La réciproque donne $(MN)\parallel(BC)$. On peut alors utiliser le théorème direct : $MN/12=2/5$, donc $\res{MN=4{,}8\ \mathrm{cm}}$. Le parallélisme est prouvé avant le calcul.","Séparer la réciproque du théorème direct.","assert Rational(4,10)==Rational(6,15) and 12*Rational(2,5)==Rational('4.8')",figure='th-13'),
E('Partager un segment',r"Sur une demi-droite issue de A, on place cinq intervalles égaux jusqu’à C. M est au troisième intervalle. La parallèle à CB passant par M coupe AB en N. Si $AB=10$ cm, calculer AN et expliquer l’intérêt de la construction.",r"$AM/AC=3/5$. Les triangles AMN et ACB sont emboîtés et MN est parallèle à CB. Thalès donne $AN/AB=3/5$, donc $\res{AN=6\ \mathrm{cm}}$. La méthode construit les trois cinquièmes d’un segment sans mesurer directement cette fraction.","Transférer un partage régulier par des parallèles.","assert 10*Rational(3,5)==6",figure='th-14'),
E('Deux réductions emboîtées',r"ABC est rectangle en A, avec $AB=12$ et $AC=16$ cm. Sur AB, $AM=3$ et $AP=9$ cm. Les parallèles à BC par M et P coupent AC en N et Q. Calculer AN, AQ et l’aire du quadrilatère MNQP, délimité dans l’ordre M, N, Q, P.",r"Thalès donne $AN=16\times3/12=4$ cm et $AQ=16\times9/12=12$ cm. Les triangles AMN et APQ sont rectangles en A. Leurs aires valent $3\times4/2=6$ et $9\times12/2=54$ cm$^2$. La bande M-N-Q-P a pour aire $54-6=\res{48\ \mathrm{cm}^2}$.","Soustraire les aires de deux triangles emboîtés.","assert 16*Rational(3,12)==4 and 16*Rational(9,12)==12 and Rational(9*12-3*4,2)==48",figure='th-15')
],reperes=['Thalès dans des triangles emboîtés','Réciproque et absence de parallélisme','Constructions et partage de segments','Problèmes de longueurs et d’aires'],deco='geometrie')

chapitre(15,'cosinus','Le cosinus dans le triangle rectangle','4 · Géométrie et espace',
'Hypoténuse · Côté adjacent · Longueur · Angle',
['Identifier les côtés relatifs à un angle aigu.','Calculer une longueur à l’aide du cosinus.','Déterminer un angle avec la calculatrice en degrés.'],
['Pythagore, quotients et équations simples.'],[
r'''\essSection{1}{Un rapport associé à un angle}
\begin{definition}Dans un triangle rectangle, le cosinus d’un angle aigu est le quotient longueur du côté adjacent sur longueur de l’hypoténuse. Le côté adjacent est celui qui touche l’angle sans être l’hypoténuse.\end{definition}
@FIG:cours-cosinus@
\begin{propriete}Dans ABC rectangle en A, $\cos(\widehat{ABC})=AB/BC$ et $\cos(\widehat{ACB})=AC/BC$. Pour un angle aigu, ce rapport est strictement compris entre 0 et 1. Des triangles rectangles ayant le même angle aigu donnent le même rapport, ce qui se relie à Thalès.\end{propriete}
\begin{exemple}Si $AB=6$ et $BC=10$ cm, $\cos(\widehat B)=6/10=0{,}6$. Pour l’angle C, le côté adjacent change : ce n’est plus AB mais AC. L’hypoténuse, elle, reste BC.\end{exemple}''',
r'''\essSection{2}{Choisir l’opération}
\begin{savoirfaire}[Calculer une longueur]Écrire d’abord le rapport avec les noms des côtés. Si l’hypoténuse $h$ et l’angle $\alpha$ sont connus, le côté adjacent vaut $h\cos\alpha$. Si l’adjacent $a$ est connu, l’hypoténuse vaut $a/\cos\alpha$.\end{savoirfaire}
\begin{exemple}Pour un angle de $40^\circ$ et une hypoténuse de 12 cm, l’adjacent vaut $12\cos40^\circ\approx9{,}19$ cm. Pour un adjacent de 7 cm au même angle, l’hypoténuse vaut $7/\cos40^\circ\approx9{,}14$ cm.\end{exemple}
\begin{savoirfaire}[Retrouver un angle]À partir de $\cos\alpha=0{,}6$, utiliser la commande cosinus inverse, souvent $\cos^{-1}$ ou arccos. En mode degrés, on trouve $\alpha\approx53{,}13^\circ$. La commande inverse ne signifie pas $1/\cos$.\end{savoirfaire}
\begin{attention}Vérifier le mode degrés de la calculatrice. La formule ne s’applique ici qu’à un triangle rectangle et à un angle aigu. Pour l’arrondi final, conserver la valeur complète du cosinus dans les calculs intermédiaires. Sinus et tangente ne sont pas nécessaires dans cette édition de Quatrième.\end{attention}'''],[
E('Nommer les côtés',r"ABC est rectangle en A. Pour l’angle B, nommer l’hypoténuse et le côté adjacent.",r"L’hypoténuse est $\res{BC}$, opposée à l’angle droit en A. Pour l’angle B, le côté adjacent qui n’est pas l’hypoténuse est $\res{AB}$. AC est opposé à l’angle B.","Repérer d’abord l’angle droit, puis l’angle étudié.","assert 'BC'!='AB'",figure='cos-01'),
E('Calculer un cosinus',r"ABC est rectangle en A, avec $AB=6$ et $BC=10$ cm. Donner le cosinus de l’angle B.",r"Le côté adjacent à B est AB et l’hypoténuse BC. Donc $\cos\widehat B=6/10=\res{3/5=0{,}6}$. Le quotient est bien entre 0 et 1.","Écrire adjacent sur hypoténuse.","assert Rational(6,10)==Rational(3,5)",figure='cos-02'),
E('Changer d’angle',r"ABC est rectangle en A, $AC=8$ cm et $BC=10$ cm. Donner le cosinus de l’angle C.",r"Pour C, le côté adjacent est AC. Ainsi $\cos\widehat C=AC/BC=8/10=\res{0{,}8}$. Le côté adjacent dépend de l’angle choisi.","Réidentifier l’adjacent pour chaque angle.","assert Rational(8,10)==Rational('.8')",figure='cos-03'),
E('Un angle de soixante degrés',r"ABC est rectangle en A, $\widehat B=60^\circ$, $BC=12$ cm. Calculer AB, sachant $\cos60^\circ=0{,}5$.",r"$AB/12=\cos60^\circ=0{,}5$. Donc $AB=12\times0{,}5=\res6$ cm. On multiplie l’hypoténuse par le cosinus pour obtenir l’adjacent.","Isoler le numérateur du rapport.","assert 12*cos(pi/3)==6",figure='cos-04'),
E('Une longueur approchée',r"ABC est rectangle en A, $\widehat B=35^\circ$ et $BC=8$ cm. Calculer AB au centième.",r"$AB=8\cos35^\circ\approx\res{6{,}55\ \mathrm{cm}}$. Le côté adjacent est plus petit que l’hypoténuse 8 cm, ce qui contrôle l’ordre de grandeur.","Multiplier par le cosinus en mode degrés.","assert round(float(8*cos(35*pi/180)),2)==6.55",figure='cos-05'),
E('Retrouver l’hypoténuse',r"ABC est rectangle en A, $\widehat B=40^\circ$ et $AB=7$ cm. Calculer BC au centième.",r"$\cos40^\circ=7/BC$. Donc $BC=7/\cos40^\circ\approx\res{9{,}14\ \mathrm{cm}}$. BC doit dépasser 7 cm ; multiplier par le cosinus aurait donné une longueur trop petite.","Diviser l’adjacent par le cosinus.","assert round(float(7/cos(40*pi/180)),2)==9.14",figure='cos-06'),
E('Déterminer un angle',r"ABC est rectangle en A avec $AB=5$ et $BC=13$ cm. Calculer l’angle B au degré près.",r"$\cos\widehat B=5/13$. La commande cosinus inverse en degrés donne $\widehat B\approx67{,}38^\circ$, soit $\res{67^\circ}$ au degré près.","Utiliser le cosinus inverse du rapport exact.","assert round(math.degrees(math.acos(5/13)))==67",figure='cos-07'),
E('Un angle puis l’autre',r"ABC est rectangle en A, $AB=9$ et $BC=15$ cm. Calculer les angles B et C au dixième.",r"$\widehat B=\arccos(9/15)\approx\res{53{,}1^\circ}$. Les deux angles aigus sont complémentaires : $\widehat C=90^\circ-\widehat B\approx\res{36{,}9^\circ}$. Utiliser l’angle non arrondi pour le second calcul.","Utiliser le complément à 90 degrés.","assert round(math.degrees(math.acos(9/15)),1)==53.1 and round(90-math.degrees(math.acos(9/15)),1)==36.9",figure='cos-08'),
E('L’adjacent à C',r"ABC est rectangle en A, $\widehat C=50^\circ$ et $BC=10$ cm. Calculer AC au centième.",r"Pour l’angle C, AC est l’adjacent. $AC=10\cos50^\circ\approx\res{6{,}43\ \mathrm{cm}}$. L’autre petit côté ne figure pas dans ce rapport.","Associer le bon petit côté à l’angle donné.","assert round(float(10*cos(50*pi/180)),2)==6.43",figure='cos-09'),
E('Une hypothèse manquante',r"Un triangle ABC a $AB=6$ et $BC=10$ cm, sans information d’angle droit. Peut-on écrire $\cos\widehat B=6/10$ ?",r"Non : la formule adjacent sur hypoténuse de ce chapitre suppose un triangle rectangle, ici en A. Deux longueurs seules ne donnent pas cette hypothèse. Il faut la connaître ou la démontrer avant d’appliquer le rapport.","Contrôler les conditions du théorème.","assert 6+7>10 and 6**2+7**2!=10**2",figure='cos-10'),
E('Inclinaison d’une échelle',r"Dans un modèle, une échelle de 4 m s’appuie sur un mur perpendiculaire au sol. Son pied est à 1,5 m du mur. Calculer son angle avec le sol au degré près et la hauteur atteinte au centimètre.",r"Pour l’angle au sol, adjacent = 1,5 et hypoténuse = 4. L’angle vaut $\arccos(1{,}5/4)\approx\res{68^\circ}$. Pythagore donne $h=\sqrt{4^2-1{,}5^2}\approx\res{3{,}71\ \mathrm m}$.","Combiner cosinus pour l’angle et Pythagore pour la hauteur.","assert round(math.degrees(math.acos(1.5/4)))==68 and round(float(sqrt(16-Rational('1.5')**2)),2)==3.71",figure='cos-11'),
E('Une rampe',r"Une rampe rectiligne mesure 6 m ; sa projection horizontale mesure 5,7 m. Quel angle fait-elle avec l’horizontale, au dixième de degré ?",r"La rampe est l’hypoténuse du triangle rectangle. $\cos\alpha=5{,}7/6=0{,}95$, donc $\alpha=\arccos(0{,}95)\approx\res{18{,}2^\circ}$. La faible différence entre les deux longueurs correspond à une inclinaison modérée.","Identifier projection adjacente et longueur inclinée.","assert round(math.degrees(math.acos(5.7/6)),1)==18.2",figure='cos-12'),
E('Un chemin incliné',r"Un chemin rectiligne de 3,2 km monte avec un angle de $27^\circ$ par rapport à l’horizontale. Calculer sa projection horizontale au centième de km.",r"La projection est le côté adjacent, le chemin l’hypoténuse. $d=3{,}2\cos27^\circ\approx\res{2{,}85\ \mathrm{km}}$. Elle est inférieure à la longueur réellement parcourue.","Multiplier l’hypoténuse par le cosinus de l’inclinaison.","assert round(float(Rational('3.2')*cos(27*pi/180)),2)==2.85",figure='cos-13'),
E('Comparer deux triangles',r"Deux triangles rectangles ont la même hypoténuse de 10 cm. Les angles étudiés valent $30^\circ$ et $60^\circ$. Comparer les côtés adjacents à ces angles.",r"Les côtés adjacents valent $10\cos30^\circ\approx\res{8{,}66}$ cm et $10\cos60^\circ=\res5$ cm. Pour cette hypoténuse commune, le côté adjacent au plus grand angle est plus court. La comparaison vient des deux calculs, pas de la seule apparence.","Conserver l’hypoténuse commune dans les deux calculs.","assert 10*cos(pi/6)>10*cos(pi/3)==5",figure='cos-14'),
E('Deux outils pour une hauteur',r"Une tour verticale AC se trouve à 9 m du point B au sol. L’angle entre BA et BC vaut $58^\circ$. Calculer BC puis la hauteur AC, au dixième de mètre.",r"ABC est rectangle en A. $\cos58^\circ=9/BC$, donc $BC=9/\cos58^\circ\approx\res{17{,}0}$ m. Avec sa valeur non arrondie, $AC=\sqrt{BC^2-9^2}\approx\res{14{,}4}$ m. Le résultat intermédiaire complet évite d’accumuler les erreurs d’arrondi.","Déterminer l’hypoténuse avant d’utiliser Pythagore.","assert round(float(9/cos(58*pi/180)),1)==17.0 and round(float(sqrt((9/cos(58*pi/180))**2-81)),1)==14.4",figure='cos-15')
],reperes=['Hypoténuse et côté adjacent','Calculer une longueur par le cosinus','Déterminer un angle en degrés','Combiner cosinus et Pythagore'],deco='geometrie')
